gdjs.GameCode.userFunc0x213f518 = function GDJSInlineCode(runtimeScene) {
"use strict";
runtimeScene.setBackgroundColor(100,100,240);
// This runs once at scene start:
if (runtimeScene.getGame().getVariables().get("musicInitialized").getAsNumber() === 0) {
  // 1) Your playlist:
  const songs = [
    "RAS Counter Of Stars.mp3",
    "RAS Cryogenic Power Nap.mp3",
    "RAS Deep Space Heart Throb.mp3",
    "RAS Eternal Machine.mp3",
    "RAS Gravity Well.mp3",
    "RAS Orbit Arboretum.mp3",
    "RAS Pillars Of Creation.mp3",
    "RAS Solar Sail.mp3"
  ];

  // 2) Pick a random index:
  const idx = Math.floor(Math.random() * songs.length);
  runtimeScene.getVariables().get("randomTrack").setNumber(idx);

  // 3) Play it on channel 1, no loop, volume 100
  gdjs.evtTools.sound.playSoundOnChannel(
    runtimeScene,
    songs[idx],
    1,    // channel
    false,// loop
    100,  // volume (0–100)
    1     // pitch
  );

  // 4) Flip our “only once” flag:
  runtimeScene.getGame().getVariables().get("musicInitialized").setNumber(1);
}

// And this code runs every frame to check if the track ended:
if (!gdjs.evtTools.sound.isSoundOnChannelPlaying(runtimeScene, 1)) {
  const songs = [
    "RAS Counter Of Stars.mp3",
    "RAS Cryogenic Power Nap.mp3",
    "RAS Deep Space Heart Throb.mp3",
    "RAS Eternal Machine.mp3",
    "RAS Gravity Well.mp3",
    "RAS Orbit Arboretum.mp3",
    "RAS Pillars Of Creation.mp3",
    "RAS Solar Sail.mp3"
  ];
  const idx = Math.floor(Math.random() * songs.length);
  runtimeScene.getVariables().get("randomTrack").setNumber(idx);

  gdjs.evtTools.sound.playSoundOnChannel(
    runtimeScene,
    songs[idx],
    1,
    false,
    100,
    1
  );
}

};
